//! PT-24: ARA 2 through CLAP, by ARA's own CLAP binding (ARACLAP.h in Celemony's ARA_API, Apache-2.0). This first step
//! reads a plug-in's ARA factories from its CLAP entry: what it is, which ARA generations it speaks, which content it
//! can analyze, how it transforms playback and how it archives its edits. Document control, analysis and playback
//! rendering build on it. ARA's C API itself is in ara_sys.rs (generated by bindgen from ARAInterface.h).
use crate::ara_sys::*;
use clap_sys::entry::clap_plugin_entry;
use std::ffi::{c_char, CStr, CString};
use std::mem::offset_of;
use std::path::Path;

/// ARACLAP.h's clap_ara_factory_t: what a CLAP entry hands out for CLAP_EXT_ARA_FACTORY.
#[repr(C)]
pub struct clap_ara_factory {
    pub get_factory_count: Option<unsafe extern "C" fn(factory: *const clap_ara_factory) -> u32>,
    pub get_ara_factory: Option<unsafe extern "C" fn(factory: *const clap_ara_factory, index: u32) -> *const ARAFactory>,
    pub get_plugin_id: Option<unsafe extern "C" fn(factory: *const clap_ara_factory, index: u32) -> *const c_char>,
}

/// ARACLAP.h's factory ids: the final one, then the draft id plug-ins built before ARA 2.2 answer to.
pub const CLAP_EXT_ARA_FACTORY: &CStr = c"org.ara-audio.ara.factory/2";
pub const CLAP_EXT_ARA_FACTORY_COMPAT: &CStr = c"org.ara-audio.ara.factory.draft/2";

fn esc(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

unsafe fn text(p: *const c_char) -> String {
    if p.is_null() {
        String::new()
    } else {
        CStr::from_ptr(p).to_string_lossy().into_owned()
    }
}

fn quoted(items: &[String]) -> String {
    items.iter().map(|s| format!("\"{}\"", esc(s))).collect::<Vec<_>>().join(", ")
}

fn content_name(t: i64) -> String {
    match t {
        x if x == kARAContentTypeNotes as i64 => "notes".into(),
        x if x == kARAContentTypeTempoEntries as i64 => "tempo".into(),
        x if x == kARAContentTypeBarSignatures as i64 => "bar signatures".into(),
        x if x == kARAContentTypeStaticTuning as i64 => "static tuning".into(),
        x if x == kARAContentTypeKeySignatures as i64 => "key signatures".into(),
        x if x == kARAContentTypeSheetChords as i64 => "sheet chords".into(),
        x => format!("content type {x}"),
    }
}

/// One factory as JSON. ARA's convention: a plug-in's struct may predate fields added later, so a field is read only
/// when the plug-in's structSize reaches past it; one it does not implement is reported as null.
unsafe fn factory_json(f: &ARAFactory, plugin_id: &str) -> String {
    macro_rules! has {
        ($field:ident) => {
            (f.structSize as usize) >= offset_of!(ARAFactory, $field) + std::mem::size_of_val(&{ f.$field })
        };
    }
    let opt = |present: bool, value: String| if present { value } else { "null".to_string() };
    let compatible: Vec<String> = if has!(compatibleDocumentArchiveIDs) && !f.compatibleDocumentArchiveIDs.is_null() {
        (0..f.compatibleDocumentArchiveIDsCount as usize).map(|i| text(*f.compatibleDocumentArchiveIDs.add(i))).collect()
    } else {
        Vec::new()
    };
    let analyzable: Vec<String> = if has!(analyzeableContentTypes) && !f.analyzeableContentTypes.is_null() {
        (0..f.analyzeableContentTypesCount as usize).map(|i| content_name(*f.analyzeableContentTypes.add(i) as i64)).collect()
    } else {
        Vec::new()
    };
    let flags = if has!(supportedPlaybackTransformationFlags) { f.supportedPlaybackTransformationFlags as i64 } else { 0 };
    let mut transformations = Vec::new();
    if flags & kARAPlaybackTransformationTimestretch as i64 != 0 {
        transformations.push("time-stretch".to_string());
    }
    if flags & kARAPlaybackTransformationTimestretchReflectingTempo as i64 != 0 {
        transformations.push("time-stretch reflecting tempo".to_string());
    }
    if flags & kARAPlaybackTransformationContentBasedFadeAtHead as i64 != 0 {
        transformations.push("content-based fade at head".to_string());
    }
    if flags & kARAPlaybackTransformationContentBasedFadeAtTail as i64 != 0 {
        transformations.push("content-based fade at tail".to_string());
    }
    format!(
        "{{\"plugin_id\": \"{}\", \"name\": \"{}\", \"manufacturer\": \"{}\", \"version\": \"{}\", \"url\": \"{}\", \"factory_id\": \"{}\", \"api_generations\": [{}, {}], \"document_archive_id\": {}, \"compatible_archive_ids\": [{}], \"analyzable\": [{}], \"playback_transformations\": [{}], \"stores_audio_file_chunks\": {}}}",
        esc(plugin_id),
        esc(&text(f.plugInName)),
        esc(&text(f.manufacturerName)),
        esc(&text(f.version)),
        esc(&text(f.informationURL)),
        esc(&text(f.factoryID)),
        { f.lowestSupportedApiGeneration },
        { f.highestSupportedApiGeneration },
        opt(has!(documentArchiveID), format!("\"{}\"", esc(&text(f.documentArchiveID)))),
        quoted(&compatible),
        quoted(&analyzable),
        quoted(&transformations),
        opt(has!(supportsStoringAudioFileChunks), ({ f.supportsStoringAudioFileChunks } != 0).to_string()),
    )
}

/// `fwhost ara-check <plugin.clap>`: the plug-in's ARA factories as JSON (`ara` false when it offers none).
pub fn check(path: &Path) -> Result<String, String> {
    unsafe {
        let lib = libloading::Library::new(path).map_err(|e| format!("cannot load {}: {e}", path.display()))?;
        let entry: libloading::Symbol<*const clap_plugin_entry> = lib.get(b"clap_entry\0").map_err(|e| format!("no clap_entry: {e}"))?;
        let entry = &**entry;
        let cpath = CString::new(path.to_string_lossy().as_bytes()).map_err(|e| e.to_string())?;
        if !(entry.init.ok_or("entry without init")?)(cpath.as_ptr()) {
            return Err("the plug-in's entry refused to initialise".into());
        }
        let get = entry.get_factory.ok_or("entry without get_factory")?;
        let mut extension = CLAP_EXT_ARA_FACTORY;
        let mut ara = get(CLAP_EXT_ARA_FACTORY.as_ptr()) as *const clap_ara_factory;
        if ara.is_null() {
            extension = CLAP_EXT_ARA_FACTORY_COMPAT;
            ara = get(CLAP_EXT_ARA_FACTORY_COMPAT.as_ptr()) as *const clap_ara_factory;
        }
        let mut factories = Vec::new();
        if !ara.is_null() {
            let count = (*ara).get_factory_count.map(|g| g(ara)).unwrap_or(0);
            for index in 0..count {
                let Some(f) = (*ara).get_ara_factory.map(|g| g(ara, index)).filter(|f| !f.is_null()) else { continue };
                let plugin_id = (*ara).get_plugin_id.map(|g| text(g(ara, index))).unwrap_or_default();
                factories.push(factory_json(&*f, &plugin_id));
            }
        }
        if let Some(deinit) = entry.deinit {
            deinit();
        }
        drop(lib);
        Ok(format!(
            "{{\"path\": \"{}\", \"ara\": {}, \"extension\": {}, \"factories\": [{}]}}",
            esc(&path.display().to_string()),
            !factories.is_empty(),
            if factories.is_empty() { "null".to_string() } else { format!("\"{}\"", esc(&extension.to_string_lossy())) },
            factories.join(", ")
        ))
    }
}
